schema:
node Item {
  vec: String @key
}
node Org {
  title: [F64]?
}
node Place {
  vec: I64 @key
}
edge Knows: Place -> Org
edge Owns: Item -> Org

query:
query q16($arg1: String) {
  match {
    $i1 owns $o2
    $p3: Place
    $o2 knows $p3
    fuzzy($i1.vec, $arg1, 3)
  }
  return { $o2.title }
}
